def distance_to_boundary(x,y):
 out=[]
 for a,b in zip(OUTLINE,OUTLINE[1:]+OUTLINE[:1]):
  dx,dy=b[0]-a[0],b[1]-a[1];q=max(0,min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy)));out.append(math.hypot(x-a[0]-q*dx,y-a[1]-q*dy))
 return min(out)
def height(x,y):return .00065+.0025*(1-math.exp(-distance_to_boundary(x,y)/.0028))
